class StockSpanner:
    def __init__(self):
        self.prices = []                                                   # remember every price seen so far, in order

    def next(self, price):
        span = 1
        i = len(self.prices) - 1
        while i >= 0 and self.prices[i] <= price:                          # walk backward while prices are <= today's price
            span += 1
            i -= 1
        self.prices.append(price)
        return span


if __name__ == "__main__":
    spanner = StockSpanner()
    for p in [100, 80, 60, 70, 60, 75, 85]:
        print(spanner.next(p))

