import java.util.*;

public class Main {
    class StockSpanner {
        List<Integer> prices = new ArrayList<>();                                   // remember every price seen so far, in order

        int next(int price) {
            int span = 1;
            int i = prices.size() - 1;
            while (i >= 0 && prices.get(i) <= price) {                                  // walk backward while prices are <= today's price
                span++;
                i--;
            }
            prices.add(price);
            return span;
        }
    }

    public static void main(String[] args) {
        StockSpanner spanner = new StockSpanner();
        int[] prices = {100, 80, 60, 70, 60, 75, 85};
        for (int p : prices) System.out.println(spanner.next(p));
    }
}

