    def __init__(self):
        self.stack = []                                                     # a monotonic DECREASING stack of (price, span) pairs

    def next(self, price):
        span = 1
        while self.stack and self.stack[-1][0] <= price:                   # everything <= today's price gets absorbed into today's span
            _, prev_span = self.stack.pop()
            span += prev_span
        self.stack.append((price, span))
        return span


if __name__ == "__main__":
    spanner = StockSpanner()
