        Deque<int[]> stack = new ArrayDeque<>();                                        // a monotonic DECREASING stack of [price, span] pairs

        int next(int price) {
            int span = 1;
            while (!stack.isEmpty() && stack.peek()[0] <= price) {                          // everything <= today's price gets absorbed into today's span
                span += stack.pop()[1];
            }
            stack.push(new int[]{price, span});
            return span;
        }
    }

