#include <bits/stdc++.h>
using namespace std;

class StockSpanner {
public:
    vector<pair<int,int>> stack;                                                          // a monotonic DECREASING stack of {price, span} pairs

    int next(int price) {
        int span = 1;
        while (!stack.empty() && stack.back().first <= price) {                                // everything <= today's price gets absorbed into today's span
            span += stack.back().second;
            stack.pop_back();
        }
        stack.push_back({price, span});
        return span;
    }
};

int main() {
    StockSpanner spanner;
    vector<int> prices = {100, 80, 60, 70, 60, 75, 85};
    for (int p : prices) cout << spanner.next(p) << endl;
    return 0;
}
